def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("n must be a positive integer greater than 1.")

    # Find the smallest prime factor
    prime = 2
    while prime * prime <= n:
        if n % prime == 0:
            n //= prime
        else:
            prime += 1

    # Check if 'n' is a prime number
    if n > 1 and all(n % p for p in range(2, int(n ** 0.5) + 1)):
        return n
    else:
        raise ValueError("n must be the product of two distinct prime numbers.")

